INSERT INTO scale_formula_translations (formula_id, language_code, name, history_text, usage_text) VALUES
  ('major', 'en', 'Major', 'The major scale grew from the medieval church-mode and tonal traditions of Europe and became the main reference for modern Western harmony.', 'It is common in pop, rock, folk, country, classical, jazz, film music, and most styles built around functional major-key harmony.'),
  ('major', 'es', 'Mayor', 'La escala mayor creció a partir de las tradiciones modales medievales y tonales de Europa, y se convirtió en la referencia principal de la armonía occidental moderna.', 'Es habitual en pop, rock, folk, country, música clásica, jazz, bandas sonoras y estilos basados en la armonía funcional mayor.'),
  ('natural_minor', 'en', 'Natural minor', 'Natural minor developed from the Aeolian mode and became one of the central minor-key resources of European tonal music.', 'It is widely used in classical music, rock, metal, pop ballads, folk, film scores, and any style that wants a darker counterpart to the major scale.'),
  ('natural_minor', 'es', 'Menor natural', 'El menor natural procede del modo eólico y se convirtió en uno de los recursos centrales de la tonalidad menor de la música europea.', 'Se usa ampliamente en música clásica, rock, metal, baladas pop, folk, bandas sonoras y estilos que buscan un contraste oscuro frente a la escala mayor.'),
  ('dorian', 'en', 'Dorian', 'Dorian is an ancient Greek-named mode that survived through medieval church music and was later reinterpreted as a major-sixth minor sound.', 'It is prominent in jazz, funk, rock, folk, soul, modal film music, and grooves centered on a minor tonic with a natural sixth.'),
  ('dorian', 'es', 'Dórico', 'El dórico es un modo con nombre griego antiguo que sobrevivió en la música eclesiástica medieval y luego se reinterpretó como un sonido menor con sexta mayor.', 'Es destacado en jazz, funk, rock, folk, soul, música modal para cine y grooves centrados en una tónica menor con sexta natural.'),
  ('phrygian', 'en', 'Phrygian', 'Phrygian is a medieval church mode with an ancient Greek name, defined in modern practice by its semitone above the tonic.', 'It appears in flamenco-related music, metal, rock, folk traditions, film scores, and modal passages seeking a tense or dramatic color.'),
  ('phrygian', 'es', 'Frigio', 'El frigio es un modo eclesiástico medieval con nombre griego antiguo, definido en la práctica moderna por el semitono sobre la tónica.', 'Aparece en músicas relacionadas con el flamenco, metal, rock, tradiciones folklóricas, bandas sonoras y pasajes modales tensos o dramáticos.'),
  ('lydian', 'en', 'Lydian', 'Lydian passed from ancient and medieval modal theory into modern harmony as the bright mode with a raised fourth.', 'It is frequent in jazz, film and game music, progressive rock, folk, fusion, and soundtracks that need a floating or luminous major color.'),
  ('lydian', 'es', 'Lidio', 'El lidio pasó de la teoría modal antigua y medieval a la armonía moderna como el modo mayor luminoso con cuarta aumentada.', 'Es frecuente en jazz, música de cine y videojuegos, rock progresivo, folk, fusión y bandas sonoras de color flotante o luminoso.'),
  ('mixolydian', 'en', 'Mixolydian', 'Mixolydian comes from the medieval modal system and is heard today as a major scale with a lowered seventh.', 'It is a foundation of blues, rock, folk, country, funk, jazz, and music built around dominant or riff-based harmony.'),
  ('mixolydian', 'es', 'Mixolidio', 'El mixolidio procede del sistema modal medieval y hoy se escucha como una escala mayor con séptimo grado bemol.', 'Es fundamental en blues, rock, folk, country, funk, jazz y música basada en dominantes o riffs.'),
  ('locrian', 'en', 'Locrian', 'Locrian is the medieval mode whose unstable diminished fifth made it less common as a tonic in traditional tonal music.', 'It is used selectively in jazz, metal, contemporary composition, and experimental writing when a highly unstable minor color is wanted.'),
  ('locrian', 'es', 'Locrio', 'El locrio es el modo medieval cuyo quinto disminuido dificultó su uso como tónica en la música tonal tradicional.', 'Se usa de forma selectiva en jazz, metal, composición contemporánea y escritura experimental cuando se busca un color menor muy inestable.'),
  ('major_pentatonic', 'en', 'Major pentatonic', 'Five-note major collections appear in many ancient and folk traditions; the modern label groups a widely shared interval pattern rather than one single origin.', 'It is central to folk, country, gospel, pop, rock, blues, and many traditions where a clear melody with few harsh clashes is useful.'),
  ('major_pentatonic', 'es', 'Pentatónica mayor', 'Las colecciones mayores de cinco notas aparecen en muchas tradiciones antiguas y folklóricas; el nombre moderno agrupa un patrón compartido, no un único origen.', 'Es central en folk, country, góspel, pop, rock, blues y tradiciones donde conviene una melodía clara con pocas fricciones.'),
  ('minor_pentatonic', 'en', 'Minor pentatonic', 'Minor pentatonic patterns are found across African, Asian, Indigenous, and European folk traditions and became especially influential through the blues.', 'It is essential to blues, rock, soul, funk, metal, folk, and improvisation because its compact shape works over many minor and dominant grooves.'),
  ('minor_pentatonic', 'es', 'Pentatónica menor', 'Los patrones pentatónicos menores aparecen en tradiciones africanas, asiáticas, indígenas y europeas, y adquirieron una influencia especial a través del blues.', 'Es esencial en blues, rock, soul, funk, metal, folk e improvisación por funcionar sobre muchos grooves menores y dominantes.'),
  ('phrygian_dominant', 'en', 'Phrygian dominant', 'Phrygian dominant is the fifth mode of harmonic minor and became a convenient modern name for a sound long present in Mediterranean and Middle Eastern-influenced music.', 'It is strongly associated with flamenco, klezmer, metal, film music, fusion, and dominant chords with a tense flat second and major third.'),
  ('phrygian_dominant', 'es', 'Frigia dominante', 'El frigio dominante es el quinto modo del menor armónico y un nombre moderno para un sonido presente desde hace tiempo en músicas mediterráneas y con influencias de Oriente Medio.', 'Se asocia especialmente con flamenco, klezmer, metal, cine, fusión y acordes dominantes con segunda bemol y tercera mayor.'),
  ('hungarian_minor', 'en', 'Hungarian minor', 'Hungarian minor is a nineteenth-century European art-music label for a scale combining augmented seconds and a distinctive raised fourth.', 'It is used in Romantic and modern classical music, metal, film scores, gypsy-jazz-influenced writing, and virtuosic improvisation.'),
  ('hungarian_minor', 'es', 'Menor húngara', 'El menor húngaro es un nombre de la música artística europea del siglo XIX para una escala con segundas aumentadas y cuarta elevada.', 'Se usa en música clásica romántica y moderna, metal, bandas sonoras, escritura con influencia gitana y la improvisación virtuosa.'),
  ('byzantine', 'en', 'Byzantine', 'The Byzantine scale is a modern Western label applied to a collection related to several Middle Eastern and Eastern Mediterranean modal practices.', 'It is used in soundtrack writing, metal, fusion, and music seeking an ornate, dramatic color; the label should not be treated as a single universal tradition.'),
  ('byzantine', 'es', 'Bizantina', 'La escala bizantina es una etiqueta occidental moderna aplicada a una colección relacionada con varias prácticas modales de Oriente Medio y el Mediterráneo oriental.', 'Se usa en bandas sonoras, metal, fusión y música de color dramático; la etiqueta no representa una única tradición universal.'),
  ('enigmatic', 'en', 'Enigmatic', 'The Enigmatic scale was introduced by Giuseppe Verdi in the late nineteenth century for his Ave Maria and became a subject of later harmonic study.', 'It is mostly heard in modern classical, film, progressive rock, jazz, and experimental harmony because of its unusual clustered color.'),
  ('enigmatic', 'es', 'Enigmática', 'La escala enigmática fue presentada por Giuseppe Verdi a finales del siglo XIX para su Ave Maria y luego fue estudiada por la armonía posterior.', 'Se escucha sobre todo en música clásica moderna, cine, rock progresivo, jazz y armonía experimental por su color inusual.'),
  ('prometheus', 'en', 'Prometheus', 'Prometheus is associated with Alexander Scriabin, who used its six-note form as a central harmonic resource in his late music.', 'It is used in twentieth-century classical music, impressionist-influenced harmony, film scoring, progressive rock, and quartal or synthetic chord writing.'),
  ('prometheus', 'es', 'Prometheus', 'Prometheus se asocia con Alexander Scriabin, quien utilizó su forma de seis notas como recurso armónico central en su música tardía.', 'Se usa en música clásica del siglo XX, armonía de influencia impresionista, bandas sonoras, rock progresivo y escritura de acordes cuartales.'),
  ('persian', 'en', 'Persian', 'Persian is a modern theoretical name for a collection related to Persian and neighboring modal sounds, though its equal-tempered form is only an approximation of living traditions.', 'It is used in film music, metal, fusion, contemporary composition, and arrangements that want an intense chromatic and augmented-second color.'),
  ('persian', 'es', 'Persa', 'Persa es un nombre teórico moderno para una colección relacionada con sonidos modales persas y vecinos, aunque su versión temperada es solo una aproximación.', 'Se usa en cine, metal, fusión, composición contemporánea y arreglos que buscan un color intenso con cromatismo y segundas aumentadas.'),
  ('egyptian', 'en', 'Egyptian', 'Egyptian is a modern Western name for a suspended pentatonic pattern often compared with collections found in several ancient and global musical contexts.', 'It is common in film and game scores, folk-inspired writing, ambient music, and improvisation over open or suspended harmonies.'),
  ('egyptian', 'es', 'Egipcia', 'Egipcia es un nombre occidental moderno para un patrón pentatónico suspendido que se compara con colecciones de varios contextos antiguos y globales.', 'Es común en bandas sonoras, escritura de inspiración folklórica, música ambiental e improvisación sobre armonías abiertas o suspendidas.'),
  ('oriental', 'en', 'Oriental', 'Oriental is a broad twentieth-century Western theory label rather than a precise name for one regional tradition.', 'It is used mainly in film scoring, metal, fusion, and theatrical writing for an exoticized tense color; regional musical context should be specified when relevant.'),
  ('oriental', 'es', 'Oriental', 'Oriental es una etiqueta amplia de la teoría occidental del siglo XX y no el nombre preciso de una tradición regional única.', 'Se usa principalmente en cine, metal, fusión y música teatral para un color tenso; cuando corresponde conviene especificar la región real.'),
  ('japanese', 'en', 'Japanese', 'The Japanese scale label describes a pentatonic collection used in Western teaching to approximate several Japanese melodic materials.', 'It is used in traditional and contemporary Japanese-influenced music, film and game scores, ambient music, and atmospheric melodic writing.'),
  ('japanese', 'es', 'Japonesa', 'La etiqueta japonesa describe una colección pentatónica usada en la enseñanza occidental para aproximar varios materiales melódicos japoneses.', 'Se usa en música japonesa tradicional y contemporánea, bandas sonoras de cine y videojuegos, ambient y melodías atmosféricas.'),
  ('hirajoshi', 'en', 'Hirajoshi', 'Hirajoshi is a modern Western guitar and theory label associated with a Japanese koto tuning and related pentatonic materials.', 'It is used in Japanese traditional and fusion contexts, film and game music, metal, ambient music, and guitar improvisation.'),
  ('hirajoshi', 'es', 'Hirajoshi', 'Hirajoshi es una etiqueta occidental moderna asociada con una afinación de koto japonesa y materiales pentatónicos relacionados.', 'Se usa en contextos japoneses tradicionales y de fusión, cine, videojuegos, metal, ambient e improvisación de guitarra.'),
  ('romanian', 'en', 'Romanian', 'Romanian minor, also called the Romanian scale, entered modern theory through analysis of Eastern European folk and art-music practice.', 'It appears in Romanian and Balkan-influenced music, jazz, klezmer, metal, film scores, and modal improvisation.'),
  ('romanian', 'es', 'Rumana', 'El menor rumano, o escala rumana, entró en la teoría moderna a través del análisis de prácticas folklóricas y artísticas de Europa oriental.', 'Aparece en música rumana y balcánica, jazz, klezmer, metal, bandas sonoras e improvisación modal.'),
  ('man_gong', 'en', 'Man Gong', 'Man Gong is a modern pentatonic name associated with Chinese and East Asian-inspired scale collections rather than a single standardized historical system.', 'It is used in East Asian-influenced film music, folk-inspired writing, ambient music, and melodic improvisation.'),
  ('man_gong', 'es', 'Man Gong', 'Man Gong es un nombre pentatónico moderno asociado con colecciones de inspiración china y de Asia oriental, no con un único sistema histórico estandarizado.', 'Se usa en bandas sonoras de influencia asiática, escritura folklórica, ambient e improvisación melódica.'),
  ('ritusen', 'en', 'Ritusen', 'Ritusen is a modern Western name for a pentatonic collection associated with Japanese and broader East Asian musical references.', 'It is used in Japanese-inspired composition, film and game scoring, folk fusion, ambient music, and open-sounding melodies.'),
  ('ritusen', 'es', 'Ritusen', 'Ritusen es un nombre occidental moderno para una colección pentatónica vinculada con referencias japonesas y de Asia oriental.', 'Se usa en composición de inspiración japonesa, cine, videojuegos, fusión folklórica, ambient y melodías abiertas.'),
  ('dominant_pentatonic', 'en', 'Dominant pentatonic', 'Dominant pentatonic is a modern jazz and improvisation concept that extracts a major-third, fifth, and flat-seventh dominant sound into five notes.', 'It is used in blues, jazz, funk, soul, rock, and improvisation over dominant seventh chords.'),
  ('dominant_pentatonic', 'es', 'Pentatónica dominante', 'La pentatónica dominante es un concepto moderno del jazz y la improvisación que concentra el sonido de tercera mayor, quinta y séptima bemol en cinco notas.', 'Se usa en blues, jazz, funk, soul, rock e improvisación sobre acordes de séptima dominante.'),
  ('voodoo', 'en', 'Voodoo', 'Voodoo is a modern scale label and should not be treated as a complete representation of Haitian Vodou or other African diasporic musical systems.', 'It is used mostly in Western theory exercises, film and game scoring, fusion, and rhythmically driven modal writing.'),
  ('voodoo', 'es', 'Voodoo', 'Voodoo es una etiqueta moderna de escala y no representa por sí sola los sistemas musicales completos del Vodou haitiano u otras músicas de la diáspora africana.', 'Se usa sobre todo en ejercicios de teoría occidental, bandas sonoras, fusión y escritura modal impulsada por el ritmo.'),
  ('neapolitan_major', 'en', 'Neapolitan major', 'Neapolitan major is a later theoretical construction built from the Neapolitan flat second and a bright major-mode collection.', 'It is used in classical harmony, film scoring, metal, progressive rock, and dramatic chromatic modulation.'),
  ('neapolitan_major', 'es', 'Napolitana mayor', 'El mayor napolitano es una construcción teórica posterior basada en la segunda bemol napolitana y una colección mayor brillante.', 'Se usa en armonía clásica, cine, metal, rock progresivo y modulaciones cromáticas dramáticas.'),
  ('neapolitan_minor', 'en', 'Neapolitan minor', 'Neapolitan minor combines the lowered second and lowered third associated with Neapolitan color with a raised leading tone.', 'It is used in Romantic and modern classical music, metal, film scores, and dark minor-key writing.'),
  ('neapolitan_minor', 'es', 'Napolitana menor', 'El menor napolitano combina la segunda y tercera bemoles del color napolitano con una sensible elevada.', 'Se usa en música clásica romántica y moderna, metal, bandas sonoras y escritura menor oscura.'),
  ('neapolitan_prometheus', 'en', 'Neapolitan Prometheus', 'Neapolitan Prometheus is a modern synthetic combination of Neapolitan color and the Prometheus collection associated with Scriabin.', 'It is used in contemporary classical music, film scoring, progressive music, and experimental harmonic design.'),
  ('neapolitan_prometheus', 'es', 'Napolitana Prometheus', 'El Prometheus napolitano es una combinación sintética moderna del color napolitano y la colección Prometheus asociada con Scriabin.', 'Se usa en música clásica contemporánea, bandas sonoras, música progresiva y diseño armónico experimental.'),
  ('petrushka', 'en', 'Petrushka', 'The Petrushka scale is named for Igor Stravinsky''s ballet and the bitonal clash between C and F-sharp major triads in its famous chord.', 'It is used in twentieth-century classical music, film scoring, modern ballet, and writing that seeks bright but sharply conflicting bitonality.'),
  ('petrushka', 'es', 'Petrushka', 'La escala de Petrushka recibe su nombre del ballet de Igor Stravinsky y del choque bitonal entre las tríadas mayores de Do y Fa sostenido.', 'Se usa en música clásica del siglo XX, cine, ballet moderno y escritura que busca una bitonalidad brillante pero conflictiva.'),
  ('harmonic_minor', 'en', 'Harmonic minor', 'Harmonic minor emerged from the tonal practice of raising the seventh degree to strengthen the dominant-to-tonic cadence in minor keys.', 'It is especially common in classical, flamenco, metal, neoclassical guitar, Middle Eastern-influenced writing, and dominant-tonic passages in minor.'),
  ('harmonic_minor', 'es', 'Menor armónica', 'El menor armónico surgió al elevar el séptimo grado para fortalecer la cadencia de dominante a tónica en las tonalidades menores.', 'Es especialmente común en música clásica, flamenco, metal, guitarra neoclásica, influencias de Oriente Medio y pasajes dominante-tónica en menor.'),
  ('locrian_natural_six', 'en', 'Locrian natural 6', 'Locrian natural 6 is a modern modal-theory name for a Locrian collection with the sixth degree raised, often understood as a mode of melodic minor.', 'It is used in jazz, fusion, contemporary harmony, metal, and compositions needing a diminished tonic color with a less dark sixth.'),
  ('locrian_natural_six', 'es', 'Locrio 6 natural', 'Locrio sexta natural es un nombre modal moderno para una colección locria con el sexto grado elevado, entendida a menudo como un modo del menor melódico.', 'Se usa en jazz, fusión, armonía contemporánea, metal y composiciones con una tónica disminuida y una sexta menos oscura.'),
  ('ionian_augmented', 'en', 'Ionian augmented', 'Ionian augmented is a modern modal name for the third mode of melodic minor, combining a major sound with a raised fifth.', 'It is used in jazz, fusion, contemporary classical music, film scoring, and dominant-to-major harmonic color.'),
  ('ionian_augmented', 'es', 'Jónico aumentado', 'Jónico aumentado es un nombre modal moderno para el tercer modo del menor melódico, que combina sonido mayor con quinta elevada.', 'Se usa en jazz, fusión, música clásica contemporánea, cine y colores armónicos entre dominante y mayor.'),
  ('lydian_sharp_two', 'en', 'Lydian #2', 'Lydian sharp two is a modern synthetic mode name built from a bright Lydian collection with an additionally raised second.', 'It is used in jazz, fusion, contemporary composition, film music, and highly colored modal improvisation.'),
  ('lydian_sharp_two', 'es', 'Lidio #2', 'Lidio sostenido dos es un nombre sintético moderno para una colección lidia con la segunda elevada.', 'Se usa en jazz, fusión, composición contemporánea, cine e improvisación modal muy colorida.'),
  ('ultralocrian', 'en', 'Ultralocrian', 'Ultralocrian is a modern jazz-theory name for the seventh mode of melodic minor, extending the altered dominant vocabulary.', 'It is used primarily in jazz, fusion, bebop, and advanced dominant-chord improvisation.'),
  ('ultralocrian', 'es', 'Ultralocrio', 'Ultralocrio es un nombre moderno del jazz para el séptimo modo del menor melódico y amplía el vocabulario de dominantes alteradas.', 'Se usa principalmente en jazz, fusión, bebop e improvisación avanzada sobre dominantes.'),
  ('melodic_minor', 'en', 'Melodic minor', 'The traditional melodic minor form raised the sixth and seventh degrees when melodies ascended, while modern jazz treats the ascending form as a scale in its own right.', 'It is used in classical melodic writing, jazz improvisation, fusion, contemporary harmony, and altered dominant applications.'),
  ('melodic_minor', 'es', 'Menor melódica', 'El menor melódico tradicional elevaba los grados sexto y séptimo al ascender; en el jazz moderno la forma ascendente se trata como una escala independiente.', 'Se usa en escritura melódica clásica, improvisación de jazz, fusión, armonía contemporánea y dominantes alteradas.'),
  ('dorian_flat_two', 'en', 'Dorian b2', 'Dorian flat two is a modern modal name for the second mode of harmonic major, combining a minor third and natural sixth with a lowered second.', 'It is used in jazz, metal, film scoring, contemporary classical music, and tense modal writing.'),
  ('dorian_flat_two', 'es', 'Dórico b2', 'Dórico bemol dos es un nombre modal moderno para el segundo modo del mayor armónico, con tercera menor, sexta natural y segunda bemol.', 'Se usa en jazz, metal, cine, música clásica contemporánea y escritura modal tensa.'),
  ('lydian_augmented', 'en', 'Lydian augmented', 'Lydian augmented is the fourth mode of melodic minor in modern jazz theory and joins a raised fourth with a raised fifth.', 'It is used in jazz, fusion, contemporary harmony, film scoring, and improvisation over major or augmented major sonorities.'),
  ('lydian_augmented', 'es', 'Lidio aumentado', 'Lidio aumentado es el cuarto modo del menor melódico en la teoría moderna del jazz y combina cuarta y quinta elevadas.', 'Se usa en jazz, fusión, armonía contemporánea, cine e improvisación sobre sonoridades mayores o aumentadas.'),
  ('lydian_dominant', 'en', 'Lydian dominant', 'Lydian dominant became a standard modern-jazz name for the fourth mode of melodic minor, a dominant scale with a raised fourth.', 'It is widely used in jazz, fusion, funk, film music, and improvisation over dominant seventh chords with a sharp eleventh.'),
  ('lydian_dominant', 'es', 'Lidio dominante', 'Lidio dominante se convirtió en un nombre estándar del jazz moderno para el cuarto modo del menor melódico, un dominante con cuarta elevada.', 'Se usa ampliamente en jazz, fusión, funk, cine e improvisación sobre acordes dominantes con oncena sostenida.'),
  ('mixolydian_flat_six', 'en', 'Mixolydian b6', 'Mixolydian flat six is a modern modal name for the fifth mode of melodic minor, combining a dominant sound with a minor sixth.', 'It is used in jazz, fusion, film scoring, flamenco-influenced harmony, and dominant chords resolving toward minor.'),
  ('mixolydian_flat_six', 'es', 'Mixolidio b6', 'Mixolidio bemol seis es un nombre modal moderno para el quinto modo del menor melódico, con sonido dominante y sexta menor.', 'Se usa en jazz, fusión, cine, armonía con influencia flamenca y dominantes que resuelven hacia menor.'),
  ('aeolian_flat_five', 'en', 'Aeolian b5', 'Aeolian flat five is a modern modal-theory name for a natural-minor collection with a diminished fifth.', 'It is used in jazz, metal, film scoring, contemporary classical music, and unstable minor-key passages.'),
  ('aeolian_flat_five', 'es', 'Eólico b5', 'Eolio bemol cinco es un nombre modal moderno para un menor natural con quinta disminuida.', 'Se usa en jazz, metal, cine, música clásica contemporánea y pasajes menores inestables.'),
  ('altered', 'en', 'Altered', 'The altered scale is the modern jazz name for the seventh mode of melodic minor and grew from the need to organize altered dominant tensions.', 'It is central to bebop, post-bop, fusion, and advanced jazz improvisation over dominant chords before resolution.'),
  ('altered', 'es', 'Alterada', 'La escala alterada es el nombre moderno del jazz para el séptimo modo del menor melódico y organiza las tensiones alteradas del dominante.', 'Es central en bebop, post-bop, fusión e improvisación avanzada sobre dominantes que resuelven.'),
  ('harmonic_major', 'en', 'Harmonic major', 'Harmonic major is a modern theoretical counterpart to harmonic minor, lowering the sixth degree of the major scale to intensify minor-subdominant color.', 'It is used in classical analysis, film scoring, jazz, metal, and contemporary harmony that combines major tonic color with dramatic minor-mode inflection.'),
  ('harmonic_major', 'es', 'Mayor armónica', 'El mayor armónico es el equivalente teórico moderno del menor armónico: baja el sexto grado del mayor para intensificar el color del subdominante menor.', 'Se usa en análisis clásico, cine, jazz, metal y armonía contemporánea que combina tónica mayor con una inflexión dramática menor.'),
  ('iwato', 'en', 'Iwato', 'Iwato is a modern Western name associated with Japanese pentatonic materials and a characteristic semitone and tritone profile.', 'It is used in Japanese-influenced music, film and game scores, ambient music, metal, and sparse atmospheric melodies.'),
  ('iwato', 'es', 'Iwato', 'Iwato es un nombre occidental moderno asociado con materiales pentatónicos japoneses y un perfil característico de semitono y tritono.', 'Se usa en música de influencia japonesa, bandas sonoras, ambient, metal y melodías atmosféricas austeras.'),
  ('hon_kumoi', 'en', 'Hon Kumoi Shiouzhi', 'Hon Kumoi Shiouzhi is a Western theory label for a Japanese pentatonic collection associated with koto tuning names.', 'It is used in Japanese traditional and fusion music, film and game scoring, ambient music, and modal guitar writing.'),
  ('hon_kumoi', 'es', 'Hon Kumoi Shiouzhi', 'Hon Kumoi Shiouzhi es una etiqueta occidental para una colección pentatónica japonesa asociada con nombres de afinaciones de koto.', 'Se usa en música japonesa tradicional y de fusión, cine, videojuegos, ambient y guitarra modal.'),
  ('kumoi', 'en', 'Kumoi (Hirajoshi mode)', 'Kumoi is a modern Western label connected with Japanese pentatonic and koto-related materials; names and interval forms vary between sources.', 'It is used in Japanese-influenced composition, film music, ambient music, fusion, and expressive pentatonic improvisation.'),
  ('kumoi', 'es', 'Kumoi (modo de Hirajoshi)', 'Kumoi es una etiqueta occidental moderna relacionada con materiales pentatónicos japoneses y de koto; los nombres y formas varían según la fuente.', 'Se usa en composición de influencia japonesa, cine, ambient, fusión e improvisación pentatónica expresiva.'),
  ('chinese_pentatonic', 'en', 'Chinese pentatonic', 'The Chinese pentatonic label refers to a family of pentatonic practices in Chinese music, not one universally fixed equal-tempered scale.', 'It is used in Chinese traditional and contemporary music, film and game scores, world-music fusion, and lyrical pentatonic melodies.'),
  ('chinese_pentatonic', 'es', 'Pentatónica china', 'La etiqueta pentatónica china refiere a una familia de prácticas pentatónicas de la música china, no a una única escala temperada universal.', 'Se usa en música china tradicional y contemporánea, bandas sonoras, fusión de músicas del mundo y melodías pentatónicas líricas.'),
  ('blues', 'en', 'Blues', 'The blues scale grew from African-American musical practice by combining a minor-pentatonic framework with a lowered fifth blue note.', 'It is characteristic of blues, jazz, rock, soul, gospel, R&B, funk, and expressive guitar, piano, horn, and vocal improvisation.'),
  ('blues', 'es', 'Blues', 'La escala de blues creció en la práctica musical afroestadounidense al combinar una base pentatónica menor con la quinta bemol, o nota blue.', 'Es característica del blues, jazz, rock, soul, góspel, R&B, funk e improvisación expresiva de guitarra, piano, vientos y voz.'),
  ('major_blues', 'en', 'Major blues', 'The major blues scale is a major-pentatonic collection colored by the added lowered third, reflecting the flexible major-minor language of the blues.', 'It is common in country, blues, rockabilly, gospel, jazz, soul, and melodic improvisation over dominant or major grooves.'),
  ('major_blues', 'es', 'Blues mayor', 'La escala mayor de blues es una pentatónica mayor coloreada por la tercera bemol, reflejando el lenguaje flexible entre mayor y menor del blues.', 'Es común en country, blues, rockabilly, góspel, jazz, soul e improvisación sobre grooves mayores o dominantes.'),
  ('chromatic', 'en', 'Chromatic', 'Chromatic practice developed through increasingly elaborate European polyphony and later became a general resource of modern composition.', 'It is used for passing motion, tension, modulation, ornament, and color in classical, jazz, film, metal, avant-garde, and popular music.'),
  ('chromatic', 'es', 'Cromática', 'La práctica cromática se desarrolló con la polifonía europea cada vez más elaborada y luego se volvió un recurso general de la composición moderna.', 'Se usa para movimiento de paso, tensión, modulación y ornamentación en música clásica, jazz, cine, metal, vanguardia y música popular.'),
  ('whole_tone', 'en', 'Whole tone', 'The whole-tone scale was systematized in nineteenth-century European harmony and became strongly associated with Impressionist composers.', 'It is used in impressionist classical music, jazz, film scoring, dreamlike passages, and dominant chords that need an ambiguous sound.'),
  ('whole_tone', 'es', 'Tonos enteros', 'La escala de tonos enteros se sistematizó en la armonía europea del siglo XIX y quedó muy asociada con compositores impresionistas.', 'Se usa en música clásica impresionista, jazz, bandas sonoras, pasajes oníricos y acordes dominantes de sonido ambiguo.'),
  ('diminished', 'en', 'Diminished', 'Diminished collections grew from symmetrical diminished-seventh harmony in nineteenth-century tonal music and later became a standard jazz resource.', 'It is used over diminished and dominant chords in jazz, classical music, film scores, bebop, fusion, and dramatic transition passages.'),
  ('diminished', 'es', 'Disminuida', 'Las colecciones disminuidas crecieron a partir de la armonía simétrica del acorde de séptima disminuida del siglo XIX y luego se volvieron un recurso del jazz.', 'Se usan sobre acordes disminuidos y dominantes en jazz, música clásica, cine, bebop, fusión y transiciones dramáticas.'),
  ('augmented', 'en', 'Augmented', 'The augmented scale is a symmetrical six-note collection associated with late-Romantic and twentieth-century harmonic experimentation.', 'It appears in jazz, modern classical music, film scoring, and lines that connect major and augmented sonorities with an intentionally unsettled color.'),
  ('augmented', 'es', 'Aumentada', 'La escala aumentada es una colección simétrica de seis notas asociada con la experimentación armónica tardorromántica y del siglo XX.', 'Aparece en jazz, música clásica moderna, bandas sonoras y líneas que conectan sonoridades mayores y aumentadas.'),
  ('hungarian_major', 'en', 'Hungarian major', 'Hungarian major is a modern Western theory label for a bright collection with a raised second and fourth and a lowered seventh.', 'It is used in classical and contemporary composition, film scoring, metal, fusion, and improvisation with an Eastern European or dramatic color.'),
  ('hungarian_major', 'es', 'Húngara mayor', 'El mayor húngaro es una etiqueta moderna de la teoría occidental para una colección luminosa con segunda y cuarta elevadas y séptima bemol.', 'Se usa en composición clásica y contemporánea, bandas sonoras, metal, fusión e improvisación con color de Europa oriental o dramático.'),
  ('kumoi_common', 'en', 'Kumoi', 'Kumoi common is a modern Western theory variant of the Kumoi family, whose names and interval forms vary across teaching and tuning sources.', 'It is used in Japanese-influenced composition, film and game music, ambient writing, fusion, and guitar improvisation.'),
  ('kumoi_common', 'es', 'Kumoi', 'Kumoi común es una variante teórica occidental moderna de la familia Kumoi, cuyos nombres y formas varían según las fuentes de enseñanza y afinación.', 'Se usa en composición de influencia japonesa, cine y videojuegos, ambient, fusión e improvisación de guitarra.'),
  ('insen', 'en', 'Insen', 'Insen is a modern Western name associated with Japanese shakuhachi and koto-related pentatonic materials.', 'It is used in Japanese traditional and fusion music, ambient writing, film and game scores, and melodies emphasizing semitone tension.'),
  ('insen', 'es', 'Insen', 'Insen es un nombre occidental moderno asociado con materiales pentatónicos japoneses de shakuhachi y koto.', 'Se usa en música japonesa tradicional y de fusión, ambient, cine, videojuegos y melodías que enfatizan la tensión del semitono.'),
  ('pelog', 'en', 'Pelog', 'Pelog is one of the tuning systems of Indonesian gamelan; its intervals vary by ensemble, so the equal-tempered version is only an approximation.', 'It is used in Balinese and Javanese gamelan, world-music fusion, film scoring, ambient music, and experimental composition.'),
  ('pelog', 'es', 'Pelog', 'Pelog es uno de los sistemas de afinación del gamelán indonesio; sus intervalos varían según el conjunto, por lo que la versión temperada es solo una aproximación.', 'Se usa en gamelán balinés y javanés, fusión de músicas del mundo, cine, ambient y composición experimental.'),
  ('enigmatic_verdi', 'en', 'Enigmatic (Verdi)', 'This form is associated with Verdi''s Enigmatic scale as analyzed in the late nineteenth-century Ave Maria and differs from later generic Enigmatic variants.', 'It is used in classical analysis, contemporary composition, film scoring, progressive rock, and unusual chromatic melodic writing.'),
  ('enigmatic_verdi', 'es', 'Enigmática (Verdi)', 'Esta forma se asocia con la escala enigmática de Verdi, analizada a partir del Ave Maria de finales del siglo XIX, y difiere de otras variantes enigmáticas.', 'Se usa en análisis clásico, composición contemporánea, cine, rock progresivo y escritura melódica cromática inusual.'),
  ('prometheus_scriabin', 'en', 'Prometheus (Scriabin)', 'This six-note form is associated with Scriabin''s Mystic chord and the harmonic language of his late piano and orchestral works.', 'It is used in twentieth-century classical music, film scoring, modern piano writing, progressive music, and synthetic quartal harmony.'),
  ('prometheus_scriabin', 'es', 'Prometeo (Scriabin)', 'Esta forma de seis notas se asocia con el acorde místico de Scriabin y el lenguaje armónico de sus obras tardías para piano y orquesta.', 'Se usa en música clásica del siglo XX, cine, piano moderno, música progresiva y armonía cuartal sintética.'),
  ('istrian', 'en', 'Istrian', 'Istrian is a twelve-tone equal-temperament approximation of the narrow-range Istrian folk scale, whose traditional intonation is not equal tempered.', 'It is used in arrangements inspired by Istrian and Balkan folk music, contemporary composition, film scoring, and experimental modal writing.'),
  ('istrian', 'es', 'Ístria', 'Istrian es una aproximación en doce tonos iguales de la escala folklórica de Istria, cuya afinación tradicional no es temperada.', 'Se usa en arreglos inspirados en música folklórica istriana y balcánica, composición contemporánea, cine y escritura modal experimental.'),
  ('baake_tritonic', 'en', 'Baake''s tritonic', 'Baake''s tritonic is a modern theoretical label for a three-note equal-tempered collection rather than a widely established historical folk scale.', 'It is useful in contemporary composition, minimalism, sound design, and exercises exploring symmetrical tritone relationships.'),
  ('baake_tritonic', 'es', 'Tritónica de Baake', 'La tritónica de Baake es una etiqueta teórica moderna para una colección temperada de tres notas, no una escala folklórica histórica ampliamente establecida.', 'Es útil en composición contemporánea, minimalismo, diseño sonoro y ejercicios sobre relaciones simétricas de tritono.'),
  ('far_east', 'en', 'Far East', 'Far East is a broad modern Western label for a synthetic hexatonic collection and does not identify one specific East Asian tradition.', 'It is used mainly in film and game scoring, fusion, ambient music, and atmospheric modal writing; regional references should be named precisely.'),
  ('far_east', 'es', 'Lejano Oriente', 'Far East es una etiqueta occidental amplia para una colección sintética de seis notas y no identifica una tradición específica de Asia oriental.', 'Se usa principalmente en cine, videojuegos, fusión, ambient y escritura modal atmosférica; las referencias regionales deben nombrarse con precisión.'),
  ('slendro', 'en', 'Slendro (approx.)', 'Slendro is a central Indonesian gamelan tuning system with five roughly equidistant tones, though each ensemble has its own intonation.', 'It is used in Javanese and Balinese gamelan, world-music fusion, film scoring, ambient music, and experimental works using non-Western tuning references.'),
  ('slendro', 'es', 'Slendro (aproximada)', 'Slendro es un sistema central de afinación del gamelán indonesio con cinco tonos aproximadamente equidistantes, aunque cada conjunto tiene su propia afinación.', 'Se usa en gamelán javanés y balinés, fusión de músicas del mundo, cine, ambient y obras experimentales que referencian afinaciones no occidentales.');
